import{a as e,i as t,r as n,t as r}from"./app-DbTmPHyY.js";var i=JSON.parse(`{"path":"/%E7%AC%AC09%E7%AB%A0%20%E9%A1%B9%E7%9B%AE%E8%8C%83%E5%9B%B4%E7%AE%A1%E7%90%86/9.2%20WBS%E5%88%86%E8%A7%A3.html","title":"9.2 WBS分解","lang":"zh-CN","frontmatter":{},"git":{},"filePathRelative":"第09章 项目范围管理/9.2 WBS分解.md"}`),a={name:`9.2 WBS分解.md`};function o(r,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[t(`<h1 id="_9-2-wbs分解" tabindex="-1"><a class="header-anchor" href="#_9-2-wbs分解"><span>9.2 WBS分解</span></a></h1><h2 id="定义" tabindex="-1"><a class="header-anchor" href="#定义"><span>定义</span></a></h2><p>WBS（Work Breakdown Structure，工作分解结构）是将项目可交付成果和工作分解成较小、更易于管理的组成部分的过程。</p><h2 id="wbs的作用" tabindex="-1"><a class="header-anchor" href="#wbs的作用"><span>WBS的作用</span></a></h2><h3 id="_1-明确项目范围" tabindex="-1"><a class="header-anchor" href="#_1-明确项目范围"><span>1. 明确项目范围</span></a></h3><ul><li>将项目分解为可管理的部分</li><li>明确项目的所有工作内容</li></ul><h3 id="_2-便于责任分配" tabindex="-1"><a class="header-anchor" href="#_2-便于责任分配"><span>2. 便于责任分配</span></a></h3><ul><li>每个工作包可以分配给特定的责任人</li><li>明确各部门和人员的职责</li></ul><h3 id="_3-便于进度和成本控制" tabindex="-1"><a class="header-anchor" href="#_3-便于进度和成本控制"><span>3. 便于进度和成本控制</span></a></h3><ul><li>可以对每个工作包进行进度和成本估算</li><li>便于监控和控制</li></ul><h3 id="_4-提供沟通基础" tabindex="-1"><a class="header-anchor" href="#_4-提供沟通基础"><span>4. 提供沟通基础</span></a></h3><ul><li>WBS是项目团队沟通的基础</li><li>便于各方理解项目结构</li></ul><h2 id="wbs分解原则" tabindex="-1"><a class="header-anchor" href="#wbs分解原则"><span>WBS分解原则</span></a></h2><h3 id="_1-完整性" tabindex="-1"><a class="header-anchor" href="#_1-完整性"><span>1. 完整性</span></a></h3><ul><li>覆盖项目的所有工作</li><li>不遗漏任何必要的工作</li></ul><h3 id="_2-层次性" tabindex="-1"><a class="header-anchor" href="#_2-层次性"><span>2. 层次性</span></a></h3><ul><li>从顶层到底层逐步分解</li><li>每个层次的分解要合理</li></ul><h3 id="_3-可管理性" tabindex="-1"><a class="header-anchor" href="#_3-可管理性"><span>3. 可管理性</span></a></h3><ul><li>每个工作包的大小要适中</li><li>便于管理和控制</li></ul><h3 id="_4-独立性" tabindex="-1"><a class="header-anchor" href="#_4-独立性"><span>4. 独立性</span></a></h3><ul><li>工作包之间要相对独立</li><li>避免交叉和重叠</li></ul><h3 id="_5-可交付性" tabindex="-1"><a class="header-anchor" href="#_5-可交付性"><span>5. 可交付性</span></a></h3><ul><li>每个工作包都要有明确的可交付成果</li><li>便于验收和确认</li></ul><h2 id="wbs的结构" tabindex="-1"><a class="header-anchor" href="#wbs的结构"><span>WBS的结构</span></a></h2><h3 id="层次结构" tabindex="-1"><a class="header-anchor" href="#层次结构"><span>层次结构</span></a></h3><ul><li><strong>第一层</strong>：项目名称</li><li><strong>第二层</strong>：项目阶段或主要可交付成果</li><li><strong>第三层</strong>：具体工作包</li><li><strong>第四层及以下</strong>：更详细的工作任务</li></ul><h3 id="表示方法" tabindex="-1"><a class="header-anchor" href="#表示方法"><span>表示方法</span></a></h3><ul><li><strong>树形结构</strong>：直观展示层次关系</li><li><strong>列表结构</strong>：便于文档管理</li></ul><h2 id="wbs词典" tabindex="-1"><a class="header-anchor" href="#wbs词典"><span>WBS词典</span></a></h2><h3 id="内容" tabindex="-1"><a class="header-anchor" href="#内容"><span>内容</span></a></h3><ul><li>工作包编号</li><li>工作包名称</li><li>工作描述</li><li>负责人</li><li>进度计划</li><li>成本预算</li><li>质量标准</li></ul><h3 id="作用" tabindex="-1"><a class="header-anchor" href="#作用"><span>作用</span></a></h3><ul><li>详细描述每个工作包的内容</li><li>为项目执行提供指导</li></ul><h2 id="wbs分解步骤" tabindex="-1"><a class="header-anchor" href="#wbs分解步骤"><span>WBS分解步骤</span></a></h2><h3 id="_1-确定项目可交付成果" tabindex="-1"><a class="header-anchor" href="#_1-确定项目可交付成果"><span>1. 确定项目可交付成果</span></a></h3><ul><li>明确项目的主要交付物</li><li>列出项目的最终成果</li></ul><h3 id="_2-分解可交付成果" tabindex="-1"><a class="header-anchor" href="#_2-分解可交付成果"><span>2. 分解可交付成果</span></a></h3><ul><li>将每个可交付成果分解为子成果</li><li>逐步细化到工作包</li></ul><h3 id="_3-验证分解结果" tabindex="-1"><a class="header-anchor" href="#_3-验证分解结果"><span>3. 验证分解结果</span></a></h3><ul><li>检查分解的完整性和合理性</li><li>确保没有遗漏和重复</li></ul><h3 id="_4-创建wbs词典" tabindex="-1"><a class="header-anchor" href="#_4-创建wbs词典"><span>4. 创建WBS词典</span></a></h3><ul><li>为每个工作包编写详细说明</li><li>明确工作包的要求</li></ul><h2 id="关键考点" tabindex="-1"><a class="header-anchor" href="#关键考点"><span>关键考点</span></a></h2><ol><li><strong>WBS的定义和作用</strong></li><li><strong>WBS分解原则</strong></li><li><strong>WBS的结构和层次</strong></li></ol><h2 id="记忆口诀" tabindex="-1"><a class="header-anchor" href="#记忆口诀"><span>记忆口诀</span></a></h2><p>工作分解结构清，层层分解到活动，完整性层次可管理</p><h2 id="典型例题" tabindex="-1"><a class="header-anchor" href="#典型例题"><span>典型例题</span></a></h2><p><strong>例题</strong>：WBS分解的基本原则不包括以下哪项？ A. 完整性 B. 层次性 C. 复杂性 D. 可管理性</p><p><strong>答案</strong>：C</p><p><strong>解析</strong>：WBS分解的基本原则包括完整性、层次性、可管理性、独立性和可交付性。复杂性不是WBS分解的原则。</p>`,50)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};